contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test function takes amount and a blockTimeHint (unused except to vary inputs).
    // It sends `amount` wei to c and then checks the invariant described.
    function run(uint amount, uint /*blockTimeHint*/) public payable {
        // We only reason about calls that send exactly 10 ether to c, as that's required by C.
        require(amount == 10 ether);
        // Ensure this contract has enough balance to forward the call
        require(address(this).balance >= amount);

        // Read observable state before the call
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;
        uint beforeBlock = block.number;
        uint beforeTime = block.timestamp;

        // Make the call and record whether it reverted.
        bool reverted;
        try c.f{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the call
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint afterBlock = block.number;
        uint afterTime = block.timestamp;

        // General rule:
        // If the call reverted, then nothing observable in c's state changed (pastBlockTime and balance unchanged).
        // If the call succeeded, then pastBlockTime became equal to the current block.timestamp (afterTime)
        // and balance either increased by 10 ether (normal case) or became 0 when block.number % 15 == 0 (payout case).

        // Construct the assertion combining these cases.
        assert(
            reverted
            ? (afterPast == beforePast && afterBal == beforeBal)
            : (
                // when succeeded, pastBlockTime must have been updated to the timestamp at execution
                afterPast == afterTime
                // and balance change must be either +10 ether or 0 if payout triggered
                && (
                    (afterBlock % 15 == 0 && afterBal == 0)
                    || (afterBlock % 15 != 0 && afterBal == beforeBal + 10 ether)
                )
            )
        );
    }

    // Allow receiving ether to fund forwarding
    receive() external payable {}
}

