contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We'll accept parameters: amount of wei to send and a simulated block timestamp delta via a dummy uint
    // Only the amount matters for the call; the uint param is unused but shows variability.
    function run(uint unused, uint amount) public payable {
        require(address(this).balance >= amount);
        // record before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the call to fallback sending `amount`
        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule:
        // If the fallback call reverted, then state did not change: pastBlockTime remains same and balance unchanged.
        // If it did not revert and amount == 10 ether, then pastBlockTime must equal current block.timestamp and
        // either the contract balance stayed >= beforeBal (it could only increase by the sent amount) except when
        // block.number % 15 == 0 in which case the contract forwarded its entire balance to msg.sender making balance 0.
        // We express that as: when not reverted and amount == 10 ether, afterPast == block.timestamp AND
        // ( (block.number % 15 == 0 && afterBal == 0) || (block.number % 15 != 0 && afterBal == beforeBal + amount) ).

        if (reverted) {
            assert(afterPast == beforePast && afterBal == beforeBal);
        } else {
            // call succeeded
            if (amount == 10 ether) {
                assert(
                    afterPast == block.timestamp &&
                    ((block.number % 15 == 0 && afterBal == 0) || (block.number % 15 != 0 && afterBal == beforeBal + amount))
                );
            } else {
                // If amount != 10 ether but call didn't revert (shouldn't happen in correct contract), still require no accidental change
                // to pastBlockTime or balance; this guards against unexpected behavior in variants.
                assert(afterPast == beforePast && afterBal == beforeBal + amount);
            }
        }
    }

    // allow receiving Ether when C forwards funds
    receive() external payable {}
}

