contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that performs the property test
    function run(uint sendAmount, uint beforeTime, uint blockNumberModuloGuess) public payable {
        // we only drive calls with an externally provided amount; ensure we have funds
        require(address(this).balance >= sendAmount);

        // read observable before-values
        uint beforePast = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        // perform the call, capturing whether it reverts
        bool reverted;
        // call fallback by sending ether with empty calldata
        try c.f{value: sendAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values (allowed view calls)
        uint afterPast = c.pastBlockTime();
        uint afterBal = address(c).balance;
        uint ourBal = address(this).balance;

        // The general rule to assert:
        // If the call with exactly 10 ether succeeded (didn't revert) then:
        //  - pastBlockTime must have increased to some timestamp >= beforePast (block.timestamp >= beforePast),
        //    and specifically equal to the current block timestamp as observed by the contract (monotonic update).
        //  - If block.number % 15 == 0 then C transferred its entire balance to this contract (so C.balance == 0 and our balance increased by that amount),
        //    otherwise C.balance increased by exactly sendAmount.

        // We cannot read the actual block.timestamp or block.number here in a provable way against the callee's view,
        // but we can assert relationships between observed before/after values and balances.

        // Construct the asserted condition:
        // If reverted or sendAmount != 10 ether then no further guarantees — just accept that as allowed.
        // Otherwise (succeeded and sendAmount == 10 ether): afterPast must be >= beforePast, and either
        //  (a) afterBal == 0 and ourBal >= sendAmount + beforeBal (we received the contract balance), or
        //  (b) afterBal == beforeBal + sendAmount.

        assert(
            reverted || sendAmount != 10 ether || (
                // call succeeded with exactly 10 ether
                afterPast >= beforePast && (
                    (afterBal == 0 && ourBal >= sendAmount + beforeBal) ||
                    (afterBal == beforeBal + sendAmount)
                )
            )
        );
    }

    // allow receiving Ether when the tested contract transfers to this one
    receive() external payable {}
}

