    // single public entry that performs the property test
    // sendAmount: amount of wei to forward to c (must be provided by caller)
    function run(uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // observe before-values (view calls only)
        uint beforePast = c.pastBlockTime();
        uint beforeCBal = address(c).balance;
        uint beforeOurBal = address(this).balance;

        // perform the call to fallback by sending Ether to c (top-level state-changing call)
        bool success;
        (success, ) = address(c).call{value: sendAmount}("");

        // observe after-values
        uint afterPast = c.pastBlockTime();
        uint afterCBal = address(c).balance;
        uint afterOurBal = address(this).balance;

        // General rule:
        // If the low-level call returned success and the sent amount equals 10 ether,
        // then pastBlockTime must not decrease, and either c kept the payment (balance increased by 10 ether)
        // when block.number % 15 != 0, or c forwarded its entire balance (making c.balance == 0) when block.number % 15 == 0
        // In the forwarding case our balance must have increased by at least the previous c balance.
        assert(
            // If call failed, no further guarantees (we still reach assert)
            (!success) ||
            (
                // success && sendAmount == 10 ether implies the stated invariants
                (sendAmount == 10 ether &&
                    afterPast >= beforePast &&
                    (
                        // either block not a multiple of 15: c kept the 10 ether
                        ((block.number % 15) != 0 && afterCBal == beforeCBal + 10 ether)
                        ||
                        // or block is multiple of 15: c forwarded entire balance (becomes zero) and our balance increased accordingly
                        ((block.number % 15) == 0 && afterCBal == 0 && afterOurBal >= beforeOurBal + beforeCBal)
                    )
                )
                // If success but sendAmount != 10 ether, fallback should revert in original contract; but here we only assert nothing further
                || (sendAmount != 10 ether)
            )
        );
    }

    receive() external payable {}
}

