contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We need to accept Ether so that c can pay us back in some cases
    receive() external payable {}

    // single public entry performing the property-based test
    function run(uint callBlockNumber, uint callTimestamp, uint amount) public payable {
        // amount is the Ether we will send to c in the call; require we have it
        require(address(this).balance >= amount, "insufficient balance for test");
        // We only model the meaningful case where the fallback expects exactly 10 ether
        // and otherwise would revert; we let the checker vary amount to explore both paths.
        // Read prior observable state
        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        // Make the call to fallback, sending `amount` wei
        bool reverted;
        // fallback is external payable and has no name; invoke by sending to payable(c)
        // Use low-level call to trigger fallback
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        // Read after-values that are publicly observable
        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;
        uint myBalance = address(this).balance;

        // General rule expressed as a single assert:
        // If the call reverted then nothing observable in c changed (pastBlockTime and balance),
        // except that when the call reverted it must be because amount != 10 ether or timestamp not greater;
        // but we can only observe invariants: when the call reverted both pastBlockTime and balance remain as before.
        // If the call did not revert then:
        //   - pastBlockTime increased to the current block.timestamp (i.e., strictly greater than beforePast),
        //   - if block.number % 15 == 0 then c's balance becomes zero (it paid out entire balance),
        //     otherwise c's balance equals beforeBalance + amount.

        assert(
            // If reverted: no change in observables
            (reverted && afterPast == beforePast && afterBalance == beforeBalance)
            ||
            // If not reverted: pastBlockTime strictly increases and balances follow the payout rule
            (!reverted
                && afterPast > beforePast
                && (
                    // If block.number % 15 == 0 then c paid out entire balance (balance == 0)
                    (block.number % 15 == 0 && afterBalance == 0)
                    ||
                    // Otherwise, c retained the sent amount (balance increased by amount)
                    (block.number % 15 != 0 && afterBalance == beforeBalance + amount)
                )
            )
        );
    }
}

