contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We implement run to test the fallback behavior. Inputs: amount to send and a supplied blockTimeHint
    // amount must be exactly 10 ether to pass the require in C.fallback; other amounts should revert.
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward `amount` to c
        require(address(this).balance >= amount);

        // read before-values
        uint beforeTime = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        // call fallback by sending plain value to c; this will trigger require(msg.value == 10 ether)
        try c.call{value: amount}("") returns (bytes memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // - If the call reverted, nothing else is required here (we assert that reverted implies unchanged storage/balance).
        // - If the call did not revert and amount == 10 ether, then:
        //     * pastBlockTime must have increased strictly (block.timestamp > beforeTime -> afterTime == block.timestamp)
        //       We cannot call block.timestamp of c, but c stores block.timestamp into pastBlockTime when successful.
        //     * The contract's balance after the call is either equal to beforeBalance + amount (no payout),
        //       or it is 0 (drained to msg.sender) — draining can only happen when block.number % 15 == 0 in C.
        // To express this generally without referencing block.number, we assert the allowed outcomes.

        assert(
            // If reverted then c's external observable state did not change (pastBlockTime and balance unchanged)
            (reverted && afterTime == beforeTime && afterBalance == beforeBalance)
            ||
            // If did not revert then amount must have been 10 ether, pastBlockTime strictly increased to a nonzero value,
            // and balance is either increased by amount (no payout) or is zero (payout occurred).
            (!reverted && amount == 10 ether && afterTime > beforeTime && afterTime != 0 &&
                (afterBalance == beforeBalance + amount || afterBalance == 0))
        );
    }

    // allow receiving Ether so the test harness can fund this contract
    receive() external payable {}
}

